self.addEventListener('install',event=>{event.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.addAll(urls);await self.skipWaiting();})());});
self.addEventListener('activate',event=>{event.waitUntil((async()=>{for(const k of await caches.keys())if(k.startsWith(PREFIX)&&k!==CACHE)await caches.delete(k);await self.clients.claim();})());});
self.addEventListener('message',event=>{if(event.data?.type==='CHECK_CACHE')event.waitUntil((async()=>{const cache=await caches.open(CACHE);let ready=true;for(const url of urls)if(!await cache.match(url)){ready=false;break;}event.ports[0]?.postMessage({ready,count:urls.length});})());});
self.addEventListener('message',event=>{if(event.data?.type==='REPAIR_CACHE')event.waitUntil((async()=>{try{const cache=await caches.open(CACHE);await cache.addAll(urls);event.ports[0]?.postMessage({ready:true});}catch{event.ports[0]?.postMessage({ready:false});}})());});
self.addEventListener('fetch',event=>{const req=event.request;if(req.method!=='GET'||!req.url.startsWith(self.registration.scope))return;event.respondWith((async()=>{const cache=await caches.open(CACHE);const url=new URL(req.url);url.search='';let response=await cache.match(url.href);if(response)return response;if(req.mode==='navigate'){response=await cache.match(new URL('index.html',self.registration.scope).href);if(response)return response;}try{return await fetch(req);}catch{if(req.mode==='navigate')return await cache.match(new URL('offline.html',self.registration.scope).href)||new Response('Persediaan offline belum lengkap',{status:503});return new Response('Aset offline tidak tersedia',{status:503});}})());});
